def build_tree(pre, inorder):
    idx = {v: i for i, v in enumerate(inorder)}
    ii = 0
    def go(lo, hi):
        nonlocal ii
        if lo > hi: return None
        val = pre[ii]; ii += 1
        root = TreeNode(val)
        mid = idx[val]
        root.left = go(lo, mid - 1)
        root.right = go(mid + 1, hi)
        return root
    return go(0, len(inorder) - 1)

def build_tree(inorder, post):
    idx = {v: i for i, v in enumerate(inorder)}
    pi = len(post) - 1
    def go(lo, hi):
        nonlocal pi
        if lo > hi: return None
        val = post[pi]; pi -= 1
        root = TreeNode(val)
        mid = idx[val]
        root.right = go(mid + 1, hi)
        root.left = go(lo, mid - 1)
        return root
    return go(0, len(inorder) - 1)

def is_balanced(root):
    def height(n):
        if not n: return 0
        l = height(n.left)
        r = height(n.right)
        if l == -1 or r == -1 or abs(l - r) > 1:
            return -1
        return max(l, r) + 1
    return height(root) != -1

def is_balanced(root):
