def has_path_sum(root, target):
    if not root: return False
    if not root.left and not root.right:
        return target == root.val
    return has_path_sum(root.left, target - root.val) or has_path_sum(root.right, target - root.val)

def has_path_sum(root, target):
    if not root: return False
    st = [(root, target)]
    while st:
        n, rem = st.pop()
        if not n.left and not n.right and rem == n.val: return True
        if n.left: st.append((n.left, rem - n.val))
        if n.right: st.append((n.right, rem - n.val))
    return False

def flatten(root):
    if not root: return None
    st = [root]
    while st:
        n = st.pop()
        if n.right: st.append(n.right)
        if n.left: st.append(n.left)
        if st: n.right = st[-1]
        n.left = None
    return root

