def preorder_traversal(root):
    if not root: return []
    res = []; st = [root]
    while st:
        n = st.pop()
        res.append(n.val)
        if n.right: st.append(n.right)
        if n.left: st.append(n.left)
    return res

def postorder_traversal(root):
    if not root: return []
    res = []; st = [root]
    while st:
        n = st.pop()
        res.append(n.val)
        if n.left: st.append(n.left)
        if n.right: st.append(n.right)
    return res[::-1]

class BSTIterator:
    def __init__(self, root):
        self.st = []
        self._push(root)
    def _push(self, n):
        while n: self.st.append(n); n = n.left
    def next(self):
        n = self.st.pop()
        self._push(n.right)
        return n.val
    def hasNext(self):
        return bool(self.st)

class BSTIterator:
    def __init__(self, root):
        self.a = []; self.i = 0
        def dfs(n):
            if not n: return
            dfs(n.left); self.a.append(n.val); dfs(n.right)
        dfs(root)
    def next(self):
        v = self.a[self.i]; self.i += 1; return v
    def hasNext(self):
        return self.i < len(self.a)

