def count_nodes(root):
    if not root: return 0
    def height(n):
        h = 0
        while n: h += 1; n = n.left
        return h
    hl = height(root.left); hr = height(root.right)
    if hl == hr:
        return (1 << hl) + count_nodes(root.right)
    else:
        return (1 << hr) + count_nodes(root.left)

def count_nodes(root):
    if not root: return 0
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def invert_tree(root):
    st = [root]
    while st:
        n = st.pop()
        if n:
            n.left, n.right = n.right, n.left
            st.append(n.left); st.append(n.right)
    return root

