def rob(root):
    def dfs(n):
        if not n: return (0, 0)
        l0, l1 = dfs(n.left)
        r0, r1 = dfs(n.right)
        return (max(l0, l1) + max(r0, r1), n.val + l0 + r0)
    return max(dfs(root))

def rob(root):
    memo = {}
    def dfs(n):
        if not n: return 0
        if n in memo: return memo[n]
        take = n.val
        if n.left: take += dfs(n.left.left) + dfs(n.left.right)
        if n.right: take += dfs(n.right.left) + dfs(n.right.right)
        skip = dfs(n.left) + dfs(n.right)
        memo[n] = max(take, skip)
        return memo[n]
    return dfs(root)

def sum_of_left_leaves(root):
    if not root: return 0
    s = 0
    st = [root]
    while st:
        n = st.pop()
        if n.left:
            if not n.left.left and not n.left.right:
                s += n.left.val
            else:
                st.append(n.left)
        if n.right:
            st.append(n.right)
    return s

def path_sum(root, targetSum):
    def count_from(n, rem):
        if not n: return 0
        c = 1 if rem == n.val else 0
        c += count_from(n.left, rem - n.val)
        c += count_from(n.right, rem - n.val)
        return c
    if not root: return 0
    return count_from(root, targetSum) + path_sum(root.left, targetSum) + path_sum(root.right, targetSum)

def diameter_of_binary_tree(root):
    def height(n):
        if not n: return 0
        return 1 + max(height(n.left), height(n.right))
    best = 0
    def dfs(n):
        nonlocal best
        if not n: return
        best = max(best, height(n.left) + height(n.right))
        dfs(n.left)
        dfs(n.right)
    dfs(root)
    return best

def is_subtree(root, subRoot):
    def same(a, b):
        if not a and not b: return True
        if not a or not b or a.val != b.val: return False
        return same(a.left, b.left) and same(a.right, b.right)
    if not root: return False
    if same(root, subRoot): return True
    return is_subtree(root.left, subRoot) or is_subtree(root.right, subRoot)

def is_subtree(root, subRoot):
    def ser(n):
        if not n: return '#'
        return f'({n.val},{ser(n.left)},{ser(n.right)})'
    return ser(subRoot) in ser(root)

def merge_trees(root1, root2):
    if not root1: return root2
    if not root2: return root1
    st = [(root1, root2)]
    while st:
        a, b = st.pop()
        a.val += b.val
        if a.left and b.left:
            st.append((a.left, b.left))
        elif not a.left:
            a.left = b.left
        if a.right and b.right:
            st.append((a.right, b.right))
        elif not a.right:
            a.right = b.right
    return root1

from collections import deque
def average_of_levels(root):
    if not root: return []
    res = []; q = deque([root])
    while q:
        s = 0; sz = len(q)
        for _ in range(sz):
            n = q.popleft(); s += n.val
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(s / sz)
    return res
